precedence_groups = [
    {"**"},          # right-associative
    {"*", "//"},     # left-associative
    {"+", "-"}       # left-associative
]

for ops in precedence_groups:
    if ops == {"**"}:
        i = len(tokens) - 2
        while i > 0:
            if tokens[i] in ops:
                left = tokens[i - 1]
                op = tokens[i]
                right = tokens[i + 1]

                if op == "**":
                    value = left ** right
                else:
                    return None

                tokens[i - 1:i + 2] = [value]
                i = len(tokens) - 2
            else:
                i -= 2
    else:
        i = 1
        while i < len(tokens) - 1:
            if tokens[i] in ops:
                left = tokens[i - 1]
                op = tokens[i]
                right = tokens[i + 1]

                if op == "*":
                    value = left * right
                elif op == "//":
                    value = left // right
                elif op == "+":
                    value = left + right
                elif op == "-":
                    value = left - right
                else:
                    return None

                tokens[i - 1:i + 2] = [value]
                i = max(1, i - 2)
            else:
                i += 2

return tokens[0]

